import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Preserve the original two PC Ice Lance activation/effect slices, replayed by the accepted HP plan. */
public final class FreezeAcceptedMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",H=P+"NativeAcceptedFreezeMutation",SP=P+"BattleSpellCatalog$FreezeAttackSpell",A=P+"NativeAreaMaterialAction";
 static java.net.URLClassLoader hierarchy;
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static MethodInsnNode call(MethodNode m,String owner,String name){return Arrays.stream(m.instructions.toArray()).filter(n->n instanceof MethodInsnNode c&&c.owner.equals(owner)&&c.name.equals(name)).map(n->(MethodInsnNode)n).findFirst().orElseThrow();}
 static byte[] bytes(ClassNode c,boolean frames){var w=new ClassWriter(frames?ClassWriter.COMPUTE_FRAMES:ClassWriter.COMPUTE_MAXS){protected String getCommonSuperClass(String a,String b){try{Class<?> x=Class.forName(a.replace('/','.'),false,hierarchy),y=Class.forName(b.replace('/','.'),false,hierarchy);if(x.isAssignableFrom(y))return a;if(y.isAssignableFrom(x))return b;if(x.isInterface()||y.isInterface())return "java/lang/Object";do{x=x.getSuperclass();}while(!x.isAssignableFrom(y));return x.getName().replace('.','/');}catch(Exception e){throw new IllegalStateException(e);}}};c.accept(w);return w.toByteArray();}
 static MethodNode replay(MethodNode original,boolean world){var activate=call(original,P+"BattleTimedStatus","activateFreeze");var start=(AbstractInsnNode)activate;for(int k=0;k<5;k++)start=prev(start);int target=((VarInsnNode)start).var,now=((VarInsnNode)next(next(start))).var;var stored=(VarInsnNode)next(activate);var branch=(JumpInsnNode)next(next(stored));if(branch.getOpcode()!=IFEQ)throw new AssertionError("original freeze effect gate");var end=branch.label;AbstractInsnNode cut=next(branch);while(!(cut instanceof JumpInsnNode exitJump&&exitJump.getOpcode()==GOTO)){cut=cut.getNext();if(cut==null)throw new AssertionError("original PC branch exit");}var range=new ArrayList<AbstractInsnNode>();for(var n=start;n!=cut;n=n.getNext()){if(n==null)throw new AssertionError("bounded original freeze slice");range.add(n);}var labels=new IdentityHashMap<LabelNode,LabelNode>();for(var n:original.instructions)if(n instanceof LabelNode l)labels.put(l,new LabelNode());
  var m=new MethodNode(0,"nativeFreezeAccepted"+(world?"World":"Battle"),"(L"+SP+";L"+PC+";Ljava/util/List;)V",null,new String[]{"java/io/IOException"});var vars=new HashMap<Integer,Integer>();vars.put(0,0);vars.put(2,1);vars.put(target,2);vars.put(now,4);vars.put(stored.var,6);if(!world)vars.put(53,3);
  m.instructions.add(new MethodInsnNode(INVOKESTATIC,"java/lang/System","nanoTime","()J",false));m.instructions.add(new VarInsnNode(LSTORE,4));
  for(var n:range){if(n instanceof FrameNode)continue;if(n instanceof JumpInsnNode j&&j.label!=end&&!range.contains(j.label))throw new AssertionError("external freeze replay branch");var copy=n.clone(labels);if(copy instanceof VarInsnNode v){if(!vars.containsKey(v.var))throw new AssertionError("unreviewed freeze replay local "+v.var+" world="+world);v.var=vars.get(v.var);}if(copy instanceof MethodInsnNode call&&call.owner.equals(SP)&&call.name.equals("durationSeconds")&&call.desc.equals("()I")){call.owner=H;call.name="duration";call.desc="(L"+SP+";)I";call.setOpcode(INVOKESTATIC);}m.instructions.add(copy);}m.instructions.add(labels.get(end));m.instructions.add(new InsnNode(RETURN));return m;
 }
 static void patch(ClassNode c){
  if(c.name.equals(P+"BattleTimedStatus")){var f=c.fields.stream().filter(v->v.name.equals("freezeExpiresAtNanos")&&v.desc.equals("J")).findFirst().orElseThrow();if((f.access&ACC_VOLATILE)!=0)throw new AssertionError("original expiry visibility");f.access|=ACC_VOLATILE;return;}
  if(c.name.equals(A+"$Context")){c.fields.add(new FieldNode(0,"nativeAcceptedFreezeBatch","Ljava/lang/Object;",null,null));return;}
  if(c.name.equals(A)){var old=c.methods.stream().filter(m->m.name.equals("captureOutput")).findFirst().orElseThrow();old.name="nativeFreezeAcceptedOriginalCaptureOutput";var m=new MethodNode(old.access,"captureOutput",old.desc,null,old.exceptions.toArray(String[]::new));for(int k=0;k<3;k++)m.instructions.add(new VarInsnNode(ALOAD,k));m.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"captureOutput",old.desc,false));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);return;}
  if(c.name.equals(P+"NativePlayerCommit$Queue")){var old=c.methods.stream().filter(m->m.name.equals("offer")).findFirst().orElseThrow();old.name="nativeFreezeAcceptedOriginalOffer";var wrapper=new MethodNode(old.access,"offer",old.desc,null,old.exceptions.toArray(String[]::new));wrapper.instructions.add(new VarInsnNode(ALOAD,0));wrapper.instructions.add(new VarInsnNode(ALOAD,1));wrapper.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"offer","(L"+c.name+";L"+P+"NativePlayerCommit$Event;)Z",false));wrapper.instructions.add(new InsnNode(IRETURN));c.methods.add(wrapper);int cleared=0;for(var m:c.methods)if(m.name.equals("drop"))for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals("java/util/ArrayDeque")&&call.name.equals("clear")){var x=new InsnList();x.add(new InsnNode(DUP));x.add(new MethodInsnNode(INVOKESTATIC,H,"clearEvents","(Ljava/util/ArrayDeque;)V",false));m.instructions.insertBefore(n,x);cleared++;}if(cleared!=1)throw new AssertionError("one original queue clear");return;}
  if(c.name.equals(P+"NativePlayerCommit")){var m=c.methods.stream().filter(v->v.name.equals("drain")).findFirst().orElseThrow();int dropped=0;for(var n:m.instructions.toArray())if(n instanceof FieldInsnNode f&&f.getOpcode()==GETSTATIC&&f.owner.equals(c.name)&&f.name.equals("dropped")){var x=new InsnList();x.add(new VarInsnNode(ALOAD,6));x.add(new MethodInsnNode(INVOKESTATIC,H,"abandon","(L"+P+"NativePlayerCommit$Event;)V",false));m.instructions.insertBefore(n,x);dropped++;}var handlers=new HashSet<LabelNode>();for(var t:m.tryCatchBlocks)if("java/lang/Throwable".equals(t.type))handlers.add(t.handler);if(dropped!=1||handlers.size()!=1)throw new AssertionError("exact rejected/exceptional event exits");for(var label:handlers){var n=next(label);if(!(n instanceof VarInsnNode v)||v.getOpcode()!=ASTORE)throw new AssertionError("original failure handler");var x=new InsnList();x.add(new VarInsnNode(ALOAD,6));x.add(new MethodInsnNode(INVOKESTATIC,H,"abandon","(L"+P+"NativePlayerCommit$Event;)V",false));m.instructions.insert(n,x);}var computed=new ClassNode();new ClassReader(bytes(c,true)).accept(computed,ClassReader.EXPAND_FRAMES);c.methods.set(c.methods.indexOf(m),computed.methods.stream().filter(v->v.name.equals("drain")&&v.desc.equals(m.desc)).findFirst().orElseThrow());return;}
  if(c.name.equals(P+"NativePlayerCommit$Event")||c.name.equals(P+"NativeAcceptedHpCompletion")){int ports=0;for(var m:c.methods)for(var n:m.instructions)if(n instanceof MethodInsnNode call&&(call.owner.equals(P+"NativeShockPlayerAction")&&call.name.equals("link")||call.owner.equals(P+"NativeAcceptedShockMutation")&&call.name.equals("completed"))){call.owner=H;ports++;}if(ports!=1)throw new AssertionError("one existing event/completion port");return;}
  var frame=c.methods.stream().filter(m->m.name.equals("nativeStaticOriginalFrame")).findFirst().orElseThrow();if((frame.access&ACC_SYNCHRONIZED)==0)throw new AssertionError("actual final native frame monitor");var guard=new InsnList();var allowed=new LabelNode();guard.add(new VarInsnNode(ALOAD,0));guard.add(new VarInsnNode(ALOAD,1));guard.add(new MethodInsnNode(INVOKESTATIC,H,"allowFrame","(L"+PC+";[B)Z",false));guard.add(new JumpInsnNode(IFNE,allowed));guard.add(new InsnNode(RETURN));guard.add(allowed);frame.instructions.insert(guard);
  for(boolean world:new boolean[]{false,true}){var old=c.methods.stream().filter(m->m.name.equals(world?"useClassicWorldFreezeAttackSpell":"useFreezeAttackSpell")).findFirst().orElseThrow();c.methods.add(replay(old,world));int access=old.access;String original=old.name;old.name="nativeFreezeAcceptedOriginal"+(world?"World":"Battle");old.access=0;var wrapper=new MethodNode(access,original,old.desc,null,old.exceptions.toArray(String[]::new));for(int k=0;k<3;k++)wrapper.instructions.add(new VarInsnNode(ALOAD,k));wrapper.instructions.add(new MethodInsnNode(INVOKESTATIC,H,world?"world":"battle","(L"+PC+";[BL"+SP+";)V",false));wrapper.instructions.add(new InsnNode(RETURN));c.methods.add(wrapper);
   int consumed=0,captured=0,damage=0;for(var n:old.instructions.toArray())if(n instanceof MethodInsnNode call){if(call.owner.equals(P+"CombatPlayerDamage")&&call.name.equals(world?"world":"battle")){call.owner=H;call.name=world?"damageWorld":"damageBattle";damage++;}else if(call.owner.equals(P+"BattleEraseMagicStatus")&&call.name.equals("consume")&&call.desc.equals("(L"+P+"BattleEraseMagicStatus$Lease;)Z")){call.owner=H;call.name="consume";call.desc="(L"+P+"BattleEraseMagicStatus;L"+P+"BattleEraseMagicStatus$Lease;)Z";call.setOpcode(INVOKESTATIC);consumed++;}else if(call.owner.equals(P+"BattleTimedStatus")&&call.name.equals("activateFreeze")){old.instructions.insertBefore(call,world?new InsnNode(ACONST_NULL):new VarInsnNode(ALOAD,53));call.owner=H;call.name="capture";call.desc="(L"+P+"BattleTimedStatus;JILjava/util/List;)Z";call.setOpcode(INVOKESTATIC);captured++;}}if(consumed!=1||captured!=1||damage!=1)throw new AssertionError("exact PC freeze ports");
  }
  var computed=new ClassNode();new ClassReader(bytes(c,true)).accept(computed,ClassReader.EXPAND_FRAMES);for(int k=0;k<c.methods.size();k++){var m=c.methods.get(k);if(m.name.startsWith("nativeFreezeAccepted")||m.name.equals("nativeStaticOriginalFrame"))c.methods.set(k,computed.methods.stream().filter(v->v.name.equals(m.name)&&v.desc.equals(m.desc)).findFirst().orElseThrow());}
 }
 public static void main(String[]args)throws Exception{var urls=new ArrayList<java.net.URL>();urls.add(Path.of(args[1]).toUri().toURL());try(var libs=Files.list(Path.of(System.getProperty("user.dir"),"lib"))){for(var p:libs.filter(x->x.toString().endsWith(".jar")).toList())urls.add(p.toUri().toURL());}hierarchy=new java.net.URLClassLoader(urls.toArray(java.net.URL[]::new),ClassLoader.getPlatformClassLoader());try(var j=new JarFile(args[1])){for(var name:List.of(PC,A,A+"$Context",P+"NativePlayerCommit$Event",P+"NativeAcceptedHpCompletion",P+"NativePlayerCommit$Queue",P+"NativePlayerCommit",P+"BattleTimedStatus")){var c=read(j,name);patch(c);var data=bytes(c,false);if(args[0].equals("splice")){var p=Path.of(args[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,data);}else try(var z=new JarFile(args[2])){if(!Arrays.equals(data,bytes(read(z,name),false)))throw new AssertionError(name);}}}System.out.println("PASS exact original PC Ice Lance replay slices and existing event/HP completion ports");}
}
